"""Generates lib/bridge/vag_ppe_plan_data.dart from didscout's vag-ppe profile.

Usage: python3 tool/gen_vag_ppe_plan.py ../didscout/profiles/vag-ppe.toml
"""

import sys
import tomllib
from pathlib import Path

SURVEY_MS = 180_000
ONCE_MS = 600_000
# Already read by the app's base plan under these exact commands.
BASE_PLAN = {("710", "2AB8"), ("710", "2AB6")}


def main(profile_path: str) -> None:
    profile = tomllib.loads(Path(profile_path).read_text(encoding="utf-8"))
    default_protocol = profile["protocol"]
    lines = [
        "// Generated by tool/gen_vag_ppe_plan.py from didscout's profiles/vag-ppe.toml;",
        "// do not edit by hand.",
        "",
        "class VagPpeModuleSpec {",
        "  const VagPpeModuleSpec(this.id, this.request, this.response, this.protocol, this.dids);",
        "  final String id;",
        "  final String request;",
        "  final String response;",
        "  final String protocol;",
        "  final List<VagPpeDidSpec> dids;",
        "}",
        "",
        "class VagPpeDidSpec {",
        "  const VagPpeDidSpec(this.did, this.intervalMs);",
        "  final String did;",
        "  final int intervalMs;",
        "}",
        "",
        "const vagPpeModules = <VagPpeModuleSpec>[",
    ]
    for module in profile["modules"]:
        request, response = module["request"], module.get("response")
        if response is None:
            continue
        dids = []
        for did in module["dids"]:
            if (request, did["did"]) in BASE_PLAN:
                continue
            if did["poll"] == "watch":
                interval = int(did["interval"]) * 1000
            elif did["poll"] == "once":
                interval = ONCE_MS
            else:
                interval = SURVEY_MS
            dids.append(f"    VagPpeDidSpec('{did['did']}', {interval}),")
        protocol = module.get("protocol", default_protocol)
        lines.append(f"  VagPpeModuleSpec('{module['id']}', '{request}', '{response}', '{protocol}', [")
        lines.extend(dids)
        lines.append("  ]),")
    lines.append("];")
    out = Path(__file__).resolve().parent.parent / "lib/bridge/vag_ppe_plan_data.dart"
    out.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"wrote {out}")


if __name__ == "__main__":
    main(sys.argv[1])
